def generate_questions_from_answer(answer):
    # asks a model to generate questions the answer would address
    if "twenty dollars" in answer.lower():
        return ["What does the Falcon plan cost?", "How much is the Falcon plan per month?"]
    return ["What is discussed in this answer?"]

def embed(text):
    return set(word for word in text.lower().split() if len(word) > 3)

def similarity(text_a, text_b):
    set_a, set_b = embed(text_a), embed(text_b)
    if not set_a or not set_b:
        return 0.0
    return len(set_a & set_b) / len(set_a | set_b)

def answer_relevancy(original_query, answer):
    # compares the generated questions back against the original query
    generated_questions = generate_questions_from_answer(answer)
    scores = [similarity(original_query, q) for q in generated_questions]
    return sum(scores) / len(scores)

original_query = "What does the Falcon plan cost per month?"
answer = "The Falcon plan costs twenty dollars per month and includes ten projects."

score = answer_relevancy(original_query, answer)
print("Answer relevancy check:")
print(f"Original query: {original_query}")
print(f"Generated answer: {answer}")
print(f"Relevancy score: {score:.2f}")
